$(document).ready(function(){$('#grade').change(function(){const gradeId=$(this).val();const subjectSelect=$('#subject');subjectSelect.empty();subjectSelect.append('<option value="">Sélectionnez une matière</option>');if(gradeId){$.ajax({url:`/notes/get_subjects/${gradeId}/`,type:'GET',success:function(data){if(data.success&&data.subjects.length>0){data.subjects.forEach(function(subject){subjectSelect.append(`<option value="${subject.id}">${subject.name}</option>`);});}else{alert("Aucune matière trouvée pour ce classe.");}},error:function(){alert("Erreur lors du chargement des matières.");}});}});$('#grade').change(function(){const gradeId=$(this).val();const classeSelect=$('#classe');classeSelect.empty();classeSelect.append('<option value="">Sélectionnez une Classe</option>');if(gradeId){$.ajax({url:`/notes/get_classes/${gradeId}/`,type:'GET',success:function(data){if(data.success&&data.classes.length>0){data.classes.forEach(function(classe){classeSelect.append(`<option value="${classe.id}">${classe.name}</option>`);});}else{alert("Aucune matière trouvée pour ce classe.");}},error:function(){alert("Erreur lors du chargement des classes.");}});}});$('#classe').change(function(){let classeId=$(this).val();let devoirId=$('#devoir').val();if(classeId&&devoirId){$.ajax({url:`/notes/get_students/${classeId}/${devoirId}/`,type:"GET",success:function(data){let studentsTable=$('#studentsTable');studentsTable.empty();$.each(data.students,function(index,student){studentsTable.append(`
                            <tr>
                                <td>${index + 1}</td>
                                <td>${student.name}</td>
                                <td>
                                    <input type="number" class="form-control student-score" data-student-id="${student.id}" min="0" max="20" step="0.1">
                                </td>
                            </tr>
                        `);});}});}});$('#saveNotes').click(function(){let notes=[];$('.student-score').each(function(){let studentId=$(this).data('student-id');let score=$(this).val();if(score){notes.push({student_id:studentId,score:score});}});if(notes.length>0){let csrfToken=$('input[name="csrfmiddlewaretoken"]').val();let sessionYear=$('#sessionYear').val();let subjectId=$('#subject').val();let devoirId=$('#devoir').val();let trimestreId=$('#trimestre').val();if(!sessionYear){alert("Veuillez sélectionner une année scolaire.");return;}
$.ajax({url:'/notes/notes_devoir/save/',type:"POST",contentType:"application/json",data:JSON.stringify({notes:notes,sessionyear:sessionYear,subject_id:subjectId,devoir_id:devoirId,trimestre_id:trimestreId}),headers:{'X-CSRFToken':csrfToken},success:function(response){alert(response.message);},error:function(xhr){alert(xhr.responseJSON.message||"Erreur lors de l'enregistrement des notes.");}});}else{alert("Veuillez entrer des notes pour les étudiants.");}});function resetNotes(){$('.student-score').val('');}
function loadNotes(){let classeId=$('#classe').val();let devoirId=$('#devoir').val();let subjectId=$('#subject').val();let sessionYear=$('#sessionYear').val();let trimestre=$('#trimestre').val();if(!classeId||!subjectId||!sessionYear||!trimestre||(!devoirId&&!$('#composition').val())){}
$.ajax({url:'/notes/get_notes/',type:'GET',data:{classe_id:classeId,devoir_id:devoirId,subject_id:subjectId,sessionyear_id:sessionYear,trimestre_id:trimestre,composition_id:$('#composition').val()},success:function(response){if(response.success){let notes=response.notes;$('.student-score').each(function(){let studentId=$(this).data('student-id');let note=notes.find(n=>n.student_id==studentId);if(note){$(this).val(note.score);}});}else{console.error(response.message);}},error:function(xhr){console.error("Erreur lors du chargement des notes:",xhr.responseText);}});}
$('#classe, #devoir, #subject, #sessionYear, #trimestre').change(function(){resetNotes();loadNotes();});});$(document).ready(function(){$('#trimestre').change(function(){const trimestreId=$(this).val();const devoirSelect=$('#devoir');devoirSelect.empty();devoirSelect.append('<option value="">Sélectionnez un devoir</option>');if(trimestreId){$.ajax({url:`/notes/get_devoirs/${trimestreId}/`,type:'GET',success:function(data){if(data.devoirs&&data.devoirs.length>0){data.devoirs.forEach(function(devoir){devoirSelect.append(`<option value="${devoir.id}">${devoir.name}</option>`);});}else{alert("Aucun devoir trouvé pour ce trimestre.");}},error:function(){alert("Erreur lors du chargement des devoirs.");}});}});});$(document).ready(function(){function resetNotes(){$('.student-score').val('');}
$('#classe').change(function(){resetNotes();});});;